## Environment information

**Version:** Multer v2.5.0

**Platform:** macOS (Darwin 25.6.0, arm64)

**Node.js version:** v24.22.1

**Any other relevant information:**

- Storage engine: `multer.diskStorage()`
- Configuration: `flush: true`
- Simulated filesystem error: `EIO` from `fs.fsync()`
- The issue was reproduced using a local test.

## What steps will reproduce the bug?

1. Check out Multer v2.5.0 and install the dependencies using `npm install`.
2. Configure DiskStorage with `flush: true` and a temporary upload directory.
3. Upload a valid 8,192-byte file through an Express application.
4. Simulate an `EIO` error in the `fs.fsync()` callback after the file has been written.
5. Check whether the uploaded file remains in the destination directory after the error response.

### Actual behavior

- Multer reports the `EIO` error to the application.
- The Express application's error handler returns HTTP 500 after receiving the EIO error from Multer.
- The uploaded file remains on disk despite the failed upload.
- The remaining file is 8,192 bytes and its contents match the uploaded data.

### Expected behavior

When `fs.fsync()` fails after an uploaded file has been written, Multer should clean up the stored file while preserving the original error.

### Suspected root cause

In `storage/disk.js`, an `fsync` error is propagated without removing the completed file.

In `lib/make-middleware.js`, the failed file is removed from `pendingFiles` and is never added to `uploadedFiles`, so it is excluded from the cleanup process.

### Additional context

I previously reported this issue to the maintainers and was encouraged to submit a regular bug fix PR.

I would be happy to work on a fix and add regression tests.

**Note:** The `EIO` error was simulated locally. This report does not claim that the filesystem error can be triggered remotely through HTTP requests alone.


### Reproduction test

The following test reproduces the issue in Multer v2.5.0.

<details>
<summary>Complete reproduction test</summary>

```javascript
/* eslint-env mocha */

var assert = require('assert')
var fs = require('fs')
var http = require('http')
var os = require('os')
var path = require('path')

var express = require('express')
var multer = require('../')

describe('disk storage cleanup after a flush error', function () {
  this.timeout(5000)

  var realFsync = fs.fsync
  var uploadDir
  var server
  var sockets
  var payload = Buffer.alloc(8192, 0x5a)

  beforeEach(function () {
    server = null
    sockets = new Set()
    uploadDir = undefined
    uploadDir = fs.mkdtempSync(path.join(os.tmpdir(), 'multer-flush-error-cleanup-'))
  })

  afterEach(async function () {
    // Restore even when a request, assertion, or test timeout fails.
    fs.fsync = realFsync

    try {
      if (server && server.listening) {
        await new Promise(function (resolve, reject) {
          server.close(function (err) {
            if (err) return reject(err)
            resolve()
          })
          sockets.forEach(function (socket) { socket.destroy() })
        })
      }
    } finally {
      // Only remove direct children of this test's freshly created directory.
      // No recursive deletion and no application-supplied paths are used.
      if (uploadDir) {
        fs.readdirSync(uploadDir).forEach(function (name) {
          fs.unlinkSync(path.join(uploadDir, name))
        })
        fs.rmdirSync(uploadDir)
        assert.strictEqual(fs.existsSync(uploadDir), false)
      }

      assert.strictEqual(fs.fsync, realFsync)
      console.log('    cleanup: fs.fsync restored; test directory removed')
    }
  })

  function snapshotFiles () {
    return fs.readdirSync(uploadDir).map(function (name) {
      var storedPath = path.join(uploadDir, name)
      return {
        name: name,
        size: fs.statSync(storedPath).size,
        contentMatches: fs.readFileSync(storedPath).equals(payload)
      }
    })
  }

  function postMultipart (port, body, boundary) {
    return new Promise(function (resolve, reject) {
      var req = http.request({
        hostname: '127.0.0.1',
        port: port,
        path: '/upload',
        method: 'POST',
        agent: false,
        headers: {
          'Content-Type': 'multipart/form-data; boundary=' + boundary,
          'Content-Length': body.length,
          Connection: 'close'
        }
      }, function (res) {
        var chunks = []
        res.on('data', function (chunk) { chunks.push(chunk) })
        res.on('error', reject)
        res.on('aborted', function () { reject(new Error('Response aborted')) })
        res.on('end', function () {
          try {
            resolve({
              statusCode: res.statusCode,
              body: JSON.parse(Buffer.concat(chunks).toString('utf8'))
            })
          } catch (err) {
            reject(err)
          }
        })
      })

      req.on('error', reject)
      req.setTimeout(2000, function () { req.destroy(new Error('Upload timed out')) })
      req.end(body)
    })
  }

  async function runCase (failFlush) {
    var fsyncCalls = 0
    var sizesAtFsync = []
    var errorCalls = 0
    var successCalls = 0
    var capturedError = null
    var filesAtError = null
    var injectedError = new Error('EIO: simulated fsync failure')
    injectedError.code = 'EIO'
    injectedError.syscall = 'fsync'

    fs.fsync = function (fd, cb) {
      fsyncCalls++
      sizesAtFsync.push(fs.fstatSync(fd).size)

      if (failFlush) {
        return process.nextTick(function () { cb(injectedError) })
      }

      return realFsync.call(fs, fd, cb)
    }

    try {
      var app = express()
      var storage = multer.diskStorage({ destination: uploadDir, flush: true })
      var upload = multer({ storage: storage })

      app.post('/upload', upload.single('file'), function (req, res) {
        successCalls++
        res.status(200).json({ size: req.file.size })
      })

      app.use(function (err, req, res, next) {
        errorCalls++
        capturedError = err
        filesAtError = snapshotFiles()
        res.status(500).json({ code: err.code, message: err.message })
      })

      server = http.createServer(app)
      server.on('connection', function (socket) {
        sockets.add(socket)
        socket.on('close', function () { sockets.delete(socket) })
      })

      await new Promise(function (resolve, reject) {
        server.once('error', reject)
        server.listen(0, '127.0.0.1', function () {
          server.removeListener('error', reject)
          resolve()
        })
      })

      var boundary = 'MulterFlushErrorCleanupBoundary'
      var body = Buffer.concat([
        Buffer.from('--' + boundary + '\r\n' +
          'Content-Disposition: form-data; name="file"; filename="payload.bin"\r\n' +
          'Content-Type: application/octet-stream\r\n\r\n'),
        payload,
        Buffer.from('\r\n--' + boundary + '--\r\n')
      ])

      var response = await postMultipart(server.address().port, body, boundary)
      var filesAfterResponse = snapshotFiles()

      console.log('    observation: ' + JSON.stringify({
        scenario: failFlush ? 'injected-fsync-EIO' : 'real-fsync-success',
        node: process.version,
        platform: process.platform,
        fsyncCalls: fsyncCalls,
        sizesAtFsync: sizesAtFsync,
        httpStatus: response.statusCode,
        errorHandlerCalls: errorCalls,
        successHandlerCalls: successCalls,
        error: capturedError && {
          name: capturedError.name,
          code: capturedError.code,
          syscall: capturedError.syscall,
          message: capturedError.message,
          storageErrors: capturedError.storageErrors
        },
        fileCountAtError: filesAtError && filesAtError.length,
        fileCountAfterResponse: filesAfterResponse.length,
        files: filesAfterResponse
      }))

      assert.strictEqual(fsyncCalls, 1)
      assert.deepStrictEqual(sizesAtFsync, [payload.length])

      if (failFlush) {
        assert.strictEqual(response.statusCode, 500)
        assert.strictEqual(errorCalls, 1)
        assert.strictEqual(successCalls, 0)
        assert.strictEqual(capturedError, injectedError)
        assert.strictEqual(response.body.code, 'EIO')
        assert.strictEqual(response.body.message, injectedError.message)
        assert.deepStrictEqual(capturedError.storageErrors, [])
        assert.strictEqual(filesAtError.length, 1)
      } else {
        assert.strictEqual(response.statusCode, 200)
        assert.strictEqual(errorCalls, 0)
        assert.strictEqual(successCalls, 1)
        assert.strictEqual(capturedError, null)
        assert.strictEqual(response.body.size, payload.length)
      }

      // Characterization: the error case currently leaves the complete file.
      // This asserts reproduction of the defect, not the desired cleanup behavior.
      assert.strictEqual(filesAfterResponse.length, 1)
      assert.strictEqual(filesAfterResponse[0].size, payload.length)
      assert.strictEqual(filesAfterResponse[0].contentMatches, true)
    } finally {
      fs.fsync = realFsync
    }
  }

  it('reproduces a complete orphan file after an injected fsync EIO', async function () {
    await runCase(true)
  })

  it('keeps the uploaded file when the real fsync succeeds', async function () {
    await runCase(false)
  })
})

```

</details>

### How to run

Save the code as `test/flush-error-cleanup.js`
in the Multer repository and run:

```bash
node node_modules/mocha/bin/mocha.js --reporter spec --timeout 5000 test/flush-error-cleanup.js
```

### Observed test results

```text
2 passing (52ms)
Mocha exit status: 0
```

These are characterization tests. They confirm that the
orphaned-file behavior is reproducible, not that the bug
has been fixed.

When the Busboy constructor throws (for example a `multipart/form-data` request with no boundary, or `multipart/mixed`), the middleware calls `next(err)`, but the `error`/`aborted`/`close` listeners on `req` are already attached and `isDone` is still false. If the client then disconnects, or the app destroys the request to stop reading the body, `handleRequestFailure` runs and `next` is called a second time.

```js
const multer = require('multer')
const { PassThrough } = require('stream')

const req = new PassThrough()
req.headers = { 'content-type': 'multipart/form-data', 'content-length': 100 }
req.write('test')

const errors = []
multer({ storage: multer.memoryStorage() }).single('file')(req, null, (err) => {
  errors.push(err.message)
  req.destroy()
})

req.on('close', () => setImmediate(() => console.log(errors)))
// [ 'Multipart: Boundary not found', 'Request closed' ]
```

Expected a single call: `[ 'Multipart: Boundary not found' ]`. With Express the error handler runs twice, and in a plain `http` server where the callback writes the response, the second call fails with `ERR_HTTP_HEADERS_SENT`.

multer 2.5.0, Node 24.

